INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64742346', 64742346, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'RSU DR KARIADI SEMARANG', 'Kontrak Service MRI Merk GE Type 1.5T Signa Voyager di Instalasi Radiologi Tahun 2026', 'Jasa Lainnya', 'Penunjukan Langsung', 'Jawa Tengah, Semarang (Kota)', 4700000000, 'January 2026', 'APBN - BADAN LAYANAN UMUM (F)', 0, 0, '1 Paket', 'Kontrak Service MRI Merk GE Type 1.5T Signa Voyager di Instalasi Radiologi Tahun 2026', 'Standar Lingkup Pekerjaan: a. Penyedia melakukan koordinasi dengan staf PPK penerima pekerjaan dan pengawas IPS&SRS untuk waktu pelaksanaan kegiatan preventif maintenance dan perbaikan. b. Preventif Maintenance dilaksanakan setiap 3 bulan (4 kali dalam satu tahun) sesuai dengan jadwal. c. Preventif Maintenance dilaksanakan sesuai jadwal yang disepakati antara pengawas IPS&SRS dan staf PPK penerima pekerjaan.. d. Monthly Visit (kunjungan bulanan) dilaksanakan setiap bulan pada hari sabtu sesuai dengan jadwal yang sudah dibuat. e. Jadwal preventif maintenance dan monthly visit dibuat dan disampaikan pada awal pekerjaan dan diketahui Ka IPS&SRS. f. Penyedia melakukan koordinasi dengan pengawas IPS&SRS dan user sebelum melakukan kegiatan maintenance dan perbaikan. g. Penyedia menyiapkan alat ukur dan alat kerja untuk melaksanakan Kontrak Service. h. Penyedia menyiapkan dan mengisi cek list preventif maintenance yang ditandatangani oleh pengawas IPS&SRS dan teknisi penyedia. i. Penyedia menyiapkan dan menempelkan stiker preventif maintenance yang berlogo/nama perusahaan penyedia pada setiap alat yang telah dipelihara serta ditandatangani. j. Penyedia menyiapkan service report setelah melakukan kegiatan yang ditandatangani oleh pengawas IPS&SRS dan teknisi penyedia. k. Melakukan uji fungsi alat setelah preventive maintenance maupun perbaikan yang diketahui pengawas IPS&SRS dan user. l. On site response 6 jam m. Initial response call center 24 jam selama 7 hari. n. Respon time dukungan teknisi lewat telepon maksimal 30 menit dari informasi kerusakan. o. Jaminan operasonal alat 95 % selama masa kontrak sesuai jam pelayanan. p. Kunjungan tidak terjadwal untuk melakukan pemeriksaan dan perbaikan alat jika terjadi kerusakan tidak terbatas. q. Bebas biaya untuk update pabrikan (Mandatory, Ompulsory dan Optional update). r. Jam pelayanan 07.30 – 21.00 WIB s. Operating System Software update / field Change order. t. Down time dihitung setelah 6 jam dari informasi kerusakan yang disampaikan ke WA grup. u. Down time dihentikan setelah ada persetujuan dari staf PPK penerima pekerjaan, pengawas dan pengguna. v. Penyedia menyiapkan laporan kegiatan kontrak service setiap 6 bulan yang diketahui oleh Ka.IPS&SRS. w. Re-training untuk operator dan teknisi dilakukan 1 kali setiap tahun untuk masing-masing alat, dengan materi re-training yang telah dikomunikasikan dengan pengguna atau teknisi RSDK. x. Evaluasi kinerja penyedia dilakukan minimal 1 tahun sekali yang dihadiri oleh penyedia,staf PPK penerima pekerjaan dan IPS&SRS Tambahan Lingkup Pekerjaan MRI: a. Preventif Maintenance Chiller dilaksanakan setiap 3 bulan (4 kali dalam satu tahun) sesuai dengan jadwal. b. Preventif Maintenance UPS dilaksanakan setiap 3 bulan (4 kali dalam satu tahun) sesuai dengan jadwal. c. Perbaikan MRI 1,5 T termasuk penggantian seluruh suku cadang yang dibutuhkan jika terjadi kerusakan termasuk chiller dan strategic part( Coldhed dan Helium) injektor, dan UPS. Penggantian coil 1 kali dalam satu tahun d. Upgrade ARDL (software & hardware) MRI Voyager 1.5 T Jika terdapat uraian pekerjaan yang belum masuk dalam uraian pekerjaan di atas tetapi ada pada penawaran penyedia saat HPS dibuat makan hal tersebut merupakan satu kesatuan uraian pekerjaan yang tidak terpisahkan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1763346);
