INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64761931', 64761931, 'analyze_legacy', 'Kab. Cirebon', 'kabkota', 'INSPEKTORAT', 'Belanja Sewa Bangunan Gedung Tempat Pertemuan', 'Jasa Lainnya', 'Dikecualikan', 'Jawa Barat, Cirebon (Kab.)', 375000000, 'January 2026', 'APBD', 1, 1, '1 Paket', 'Belanja sewa ruang rapat/pertemuan;', 'Biaya Paket Kegiatan Rapat atau Pertemuan di Luar Kantor Fullday (Setingkat Kepala Daerah atau Eselon I) Hotel Bintang 3;', 375000000, 'high', 'Pengadaan sewa ruang rapat/pertemuan di luar kantor pada hotel bintang 3 untuk kegiatan fullday berindikasi kurang hemat karena fungsi rapat pada prinsipnya dapat diupayakan di fasilitas kantor pemerintah. Untuk lembaga pengawasan internal, penggunaan venue hotel bagi satu paket kegiatan dengan nilai signifikan layak dikategorikan sebagai belanja yang serius untuk dicermati dari sisi kebutuhan dan efisiensi.', NULL, NULL, 3, 1, 1, 1, 1, 1763766);
