INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64743507', 64743507, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan - Analis Kebijakan Produktivitas Lingkup Makro Dalam Rangka Penguatan Landasan Konseptual Dan Perencanaan Produktivitas Pada Kerangka Ekonomi Makro', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 45818180, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '4', 'Lingkup kegiatan Utama yang akan dilakukan oleh mencakup pelaksanaan tugas koordinasi, analisis dan teknis dalam mendukung penyusunan strategi dan kebijakan produktivitas yang terintegrasi dengan perencanaan sektoral nasional. Adapun ruang lingkup kegiatan yang dimaksud antara lain sebagai berikut. 1. Pengkajian Konsep dan Kerangka Produktivitas 2. Pemetaan Isu dan Tantangan Produktivitas 3. Analisis Kebijakan Produktivitas 4. Sinkronisasi Produktivitas dan TFP dalam Kerangka Ekonomi Makro dan Financial Programming Policies (FPP) 5. Penyusunan Rekomendasi Strategis Umum', '1. Berlatar belakang Pendidikan minimal Strata-1 (S1) di bidang Ilmu Ekonomi, Ekonomi Pembangunan, Studi Pembangunan, Manajemen, Perencanaan Wilayah dan Kota, Manajemen, dan Kebijakan Publik. 2. Memiliki pengalaman kerja profesional dalam bidang yang terkait dengan perencanaan pembangunan, pengukuran dan analisis produktivitas, Total Factor Productivity (TFP), pengembangan kebijakan peningkatan produktivitas, serta koordinasi lintas sektor. 3. Memiliki pengalaman pelatihan (course) Financial Programming Policies (FPP) yang diselenggarakan oleh institusi nasional atau internasional (pengalaman internasional menjadi nilai tambah), untuk menganalisis keterkaitan sektor, keterkaitan angka Total Factor Productivity (TFP) pada sektor riil, serta estimasi kontribusinya terhadap produktivitas nasional. 4. Memiliki pemahaman mendalam mengenai isu, tren, konsep, dan kerangka kerja produktivitas serta TFP, serta pernah terlibat aktif dalam kajian atau diskusi teknis di bidang tersebut. 5. Memiliki kemampuan menyusun analisis konseptual, termasuk kajian produktivitas, framework TFP, dan hubungan antara sektor, serta kinerja pembangunan. 6. Mempunyai kemampuan dan pengalaman terlibat dalam kegiatan penyusunan RPJPN, RPJMN, RKP, kajian kebijakan lintas sektor, sinkronisasi perencanaan atau harmonisasi program K/L, dan perencanaan berbasis risiko. 7. Memiliki pemahaman yang memadai dan penguasaan dalam penyusunan laporan profesional: laporan analitis, policy paper, executive summary, dan laporan akhir. 8. Memiliki pemahaman memadai mengenai proses bisnis perencanaan pembangunan nasional dan daerah, termasuk mekanisme monitoring, evaluasi, dan pelaporan dalam konteks program produktivitas.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1764375);
