INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64743066', 64743066, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Penyusunan Kajian Analisis Pengembangan Kerangka Konseptual Ekonomi Oranye', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 48000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '4', 'Lingkup kegiatan utama pelaksanaan analisis dan teknis dalam mendukung penyusunan strategi dan kebijakan pembangunan tematik ekonomi oranye yang terintegrasi dengan perencanaan sektoral nasional antara lain sebagai berikut. 1. Kajian Konseptual dan Analisis Pemaknaan Ekonomi Oranye 2. Pemetaan Isu, Tantangan, dan Peluang Ekonomi Oranye 3. Analisis Gap Konseptual Ekonomi Oranye dan Implikasi Kebijakan 4. Penyusunan Rekomendasi Teknis 5. Dukungan Fasilitasi Diskusi dan Knowladge Sharing 6. Konsolidasi Pengetahuan dan Pembelajaran Kebijakan', '1. Berlatar belakang Pendidikan minimal Strata-1 (S1) di bidang Ilmu Ekonomi,Ekonomi Pembangunan, Studi Pembangunan, Manajemen, Perencanaan Wilayah dan Kota, Manajemen, dan Kebijakan Publik. 2. Memiliki pengalaman kerja paling kurang minimal 1 (satu) tahun dalam kegiatan kajian, analisis, atau pendampingan teknis yang berkaitan dengan pembangunan ekonomi, ekonomi oranye/ekonomi kreatif, kebudayaan, pariwisata, inovasi, atau kebijakan publik lintas sektor. 3. Memiliki pengalaman kerja minimal 3 (tiga) tahun di bidang evaluasi program, pengendalian pelaksanaan kegiatan, dan manajemen risiko, khususnya dalam konteks kebijakan dan program pembangunan, termasuk pemanfaatan hasil evaluasi dan analisis risiko sebagai dasar penyusunan rekomendasi dan perbaikan desain intervensi. 4. Memiliki pemahaman mendalam mengenai isu, tren, konsep dan kerangka kerja ekonomi oranye serta serta keterkaitannya dengan peningkatan produktivitas dan transformasi ekonomi, termasuk Total Factor Productivity (TFP). 5. Memiliki pemahaman yang memadai dan penguasaan dalam penyusunan laporan profesional: laporan analitis, policy paper, executive summary, dan laporan akhir. 6. Memiliki kemampuan menyusun laporan profesional, naskah teknis, policy note, dan ringkasan eksekutif, serta mampu mendukung pelaksanaan diskusi teknis, forum koordinasi, atau FGD sebagai fasilitator substansi, bukan sebagai pengambil keputusan. 7. Memiliki pemahaman memadai mengenai prinsip dan kerangka manajemen risiko (risk management), pengendalian internal, serta identifikasi dan mitigasi risiko kebijakan dan program pembangunan, khususnya dalam pengembangan dan implementasi ekonomi oranye lintas sektor. 8. Memiliki pemahaman memadai mengenai proses bisnis perencanaan pembangunan nasional dan daerah, termasuk mekanisme monitoring, evaluasi, dan pelaporan dalam konteks program ekonomi oranye. 9. Memiliki pengalaman pelatihan atau pemahaman teknis mengenai penyusunan tabel Input–Output (IO) untuk analisis keterkaitan sektor, pemetaan rantai nilai ekonomi oranye, serta estimasi kontribusinya terhadap produktivitas nasional yang dibuktikan dengan sertifikat pelatihan. 10. Memiliki sertifikasi di bidang Governance, Risk, and Compliance Officer (GRCO) atau sertifikasi lain yang relevan dengan tata kelola, manajemen risiko, dan kepatuhan, serta telah mengikuti pelatihan Metodologi Evaluasi yang dibuktikan dengan sertifikat pelatihan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1764573);
