INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64744420', 64744420, 'analyze_legacy', 'Badan Pusat Statistik', 'central', 'BADAN PUSAT STATISTIK KAB KUTAI BARAT', 'paket data pelatihan petugas susenas september', 'Barang', 'Pengadaan Langsung', 'Kalimantan Timur, Kutai Barat (Kab.)', 550000, 'August 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 11 OB, @Rp 50.000 )', '1. paket data pelatihan petugas susenas september ( 11 OB, @Rp 50.000 )', 'Nama Paket : paket data pelatihan petugas susenas september Volume : 11 OB (Orang Bulan) Harga Satuan : @ Rp50.000 1. Ruang Lingkup Pekerjaan Penyedia melaksanakan pengadaan dan penyaluran paket data internet/pulsa seluler untuk mendukung kegiatan pelatihan di wilayah Kabupaten Kutai Barat 2. Spesifikasi Teknis - Paket data/pulsa diberikan kepada nomor petugas pencacahan aktif. - Nilai paket data/pulsa sebesar Rp50.000 per OB. - Paket data dapat digunakan untuk akses internet dan/atau komunikasi seluler guna mendukung pelaksanaan pelatihan. - Masa aktif paket/pulsa minimal 30 (tiga puluh) hari sejak aktivasi. - Jaringan provider memiliki cakupan layanan yang memadai di wilayah domisili petugas. 3. Persyaratan - Paket data/pulsa dalam kondisi aktif dan siap digunakan. - Harga yang ditawarkan merupakan harga wajar dan sesuai harga pasar yang berlaku. - Harga sudah termasuk pajak dan biaya administrasi lainnya. - Penyedia bertanggung jawab atas keberhasilan pengisian/aktivasi paket data kepada nomor tujuan. - Apabila terjadi kegagalan pengisian, penyedia wajib melakukan penggantian tanpa biaya tambahan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1767379);
